tSapIngressIPCritSrcIpFullMask = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 16, 3, 5, 1, 22), IpAddress().clone(hexValue="00000000")).setMaxAccess("readcreate")
